// A request the platform keeps refusing cannot finish the fulfilment; after too many, it fails rather than loops.
function badRequest(s, ctx) {
  s.bad = (s.bad || 0) + 1;
  if (s.bad > MAX_BAD_REQUESTS) fail(s, 'invalid-request', ctx.now);
